function PhiMaxExact(P, n):
  # build co-activation graph G_P
  supp <- {x : P(x) > 0}
  for each pair u < v in 0..n-1:
      if exists x in supp with x[u] and x[v]:
          add edge {u,v} to G_P
  # maximum clique via Bron-Kerbosch with pivoting
  best <- empty
  function BK(R, P, X):
      if P and X both empty: if |R| > |best|: best <- R; return
      if |R| + |P| <= |best|: return        # branch-and-bound cut
      choose pivot u in P union X maximizing |N(u) cap P|
      for v in P \ N(pivot):
          BK(R + {v}, P cap N(v), X cap N(v))
          P <- P \ {v}; X <- X union {v}
  BK(empty, all vertices, empty)
  return |best| if |best| >= 2 else 0

