function GreedyPhiLowerBound(P, n):
  G_P <- coactivation_graph(P, n)
  best <- 0
  for seed in vertices sorted by degree descending:
      K <- {seed}; C <- neighbours(seed)
      while C nonempty:
          v <- argmax_{u in C} |neighbours(u) cap C|
          K <- K union {v}
          C <- (C cap neighbours(v)) \ {v}
      if |K| >= 2: best <- max(best, |K|)
  return best

